probe:
h=$0; o=$(gh pr list --head "$h" --state open --json number,body --jq '.[0] // empty | "\(.number)
\(.body)"') || exit 1; nl='
'; n=${o%%"$nl"*}; [ -n "$n" ] || exit 1; d=${o#*"$nl"}; g=; for x in "$@"; do case "$d$nl" in *"Refs #$x"[!0-9]*) ;; *) g="$g${g:+, }{"kind": "refs", "name": "Refs #$x", "reason": "PR #$n の本文に無い"}";; esac; done; if [ -n "$g" ]; then printf '{"status": "stopped", "summary": "PR #%s の本文に無い Refs がある", "cause": {"kind": "incomplete", "detail": "PR #%s の本文に無い Refs がある。本文へ足してから打ち直す"}, "gaps": [%s]}
' "$n" "$n" "$g"; exit 1; fi; printf '{"status": "ok", "summary": "PR #%s", "items": [{"kind": "pr", "number": %s}], "outputs": {"pr": %s}}
' "$n" "$n" "$n"
